import { z } from 'zod';

/**
 * A catalogue recipe's picture (recipes ADR-0003 §4): openly licensed from
 * Wikimedia Commons with its credit, licence and file page recorded, or
 * generated by NestPrep's image model with none of them. Photos from recipe
 * sites are never used, so a licence that is not one of Commons' open ones,
 * or a source that is not a Commons file page, is refused at parse time.
 */

/** CC0, CC BY and CC BY-SA, with their version — never NC or ND. */
const OPEN_LICENCE = /^(?:CC0 1\.0|CC0|CC BY \d\.\d|CC BY-SA \d\.\d)$/;
const COMMONS_FILE_PAGE = /^https:\/\/commons\.wikimedia\.org\/wiki\/File:\S+$/;

/** The two sizes every photo is published in: a list card and the recipe page. */
export const PHOTO_SIZES = ['hero', 'card'] as const;
export type PhotoSize = (typeof PHOTO_SIZES)[number];

/** What an author writes; the seed adds where the two files were published. */
export const recipePhotoSource = z
  .object({
    credit: z.string().trim().min(1).max(120).nullable(),
    licence: z.string().regex(OPEN_LICENCE).nullable(),
    sourceUrl: z.string().max(500).regex(COMMONS_FILE_PAGE).nullable(),
    generated: z.boolean(),
  })
  .strict()
  .refine(
    (photo) =>
      photo.generated
        ? photo.credit === null && photo.licence === null && photo.sourceUrl === null
        : photo.credit !== null && photo.licence !== null && photo.sourceUrl !== null,
    {
      message: 'a generated photo has no credit, licence or source; a licensed one has all three',
    },
  );
export type RecipePhotoSource = z.infer<typeof recipePhotoSource>;

/** The Storage object paths the seed published a recipe's two files at. */
export type RecipePhotoPaths = Readonly<Record<PhotoSize, string>>;

/** What `recipes/{id}.photo` holds. */
export type RecipePhotoDocument = RecipePhotoPaths & RecipePhotoSource;
